const TOOLS = [
  {
    name: 'ticket_create',
    description: 'Create a support ticket',
    inputSchema: {
      type: 'object',
      properties: {
        title: { type: 'string', description: 'Ticket title' },
        description: { type: 'string', description: 'Ticket description' },
        priority: {
          type: 'string',
          enum: ['low', 'normal', 'high'],
          description: 'Ticket priority',
        },
      },
      required: ['title', 'description'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args) {
  if (name !== 'ticket_create') {
    throw new Error(`Unknown tool: ${name}`);
  }

  // Validate required fields
  if (typeof args.title !== 'string' || args.title.trim() === '') {
    throw new Error('title is required and must be non-empty');
  }
  if (typeof args.description !== 'string' || args.description.trim() === '') {
    throw new Error('description is required and must be non-empty');
  }

  // Validate no extra fields
  const allowed = new Set(['title', 'description', 'priority']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown field: ${key}`);
    }
  }

  // Validate priority if provided
  const priority = args.priority ?? 'normal';
  if (!['low', 'normal', 'high'].includes(priority)) {
    throw new Error(`Invalid priority: ${priority}. Must be low, normal, or high`);
  }

  const id = `t${nextId++}`;

  return {
    content: [
      {
        type: 'text',
        text: `Ticket ${id} created with priority ${priority}: ${args.title}`,
      },
    ],
  };
}
"}

